package com.resumeanalyzer.security;
import com.resumeanalyzer.entity.User; import io.jsonwebtoken.*; import io.jsonwebtoken.io.Decoders; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.time.Instant; import java.util.Date;
@Service public class JwtService { private final SecretKey key; private final long expirationMs; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.expiration}") long expirationMs){this.key=Keys.hmacShaKeyFor(Decoders.BASE64.decode(secret));this.expirationMs=expirationMs;} public String generate(User user){Instant now=Instant.now();return Jwts.builder().subject(user.getEmail()).claim("role",user.getRole().name()).issuedAt(Date.from(now)).expiration(Date.from(now.plusMillis(expirationMs))).signWith(key).compact();} public String subject(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();} public boolean isValid(String token){try{subject(token);return true;}catch(JwtException|IllegalArgumentException ex){return false;}} public long expirationSeconds(){return expirationMs/1000;} }
